import{_ as a,c as d,o as e,aj as r}from"./chunks/framework.CynFBi0q.js";const x=JSON.parse('{"title":"Go实战训练营","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/go-practice/index.md","filePath":"handbook/go-practice/index.md","lastUpdated":1782318444000}'),h={name:"handbook/go-practice/index.md"};function o(i,t,l,n,b,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="go实战训练营" tabindex="-1">Go实战训练营 <a class="header-anchor" href="#go实战训练营" aria-label="Permalink to “Go实战训练营”">​</a></h1><blockquote><p><strong>课程定位</strong>：从Web框架到微服务架构，16周掌握Go后端工程化全栈能力 <strong>课程周期</strong>：16 周 / 80 小时课程内容 <strong>课程特色</strong>：手写框架 + 实战项目 + 面试冲刺，每个模块都有完整的Go代码实现</p></blockquote><h2 id="课程大纲" tabindex="-1">课程大纲 <a class="header-anchor" href="#课程大纲" aria-label="Permalink to “课程大纲”">​</a></h2><h3 id="第一模块-web框架设计-第1-3章" tabindex="-1">第一模块：Web框架设计（第1-3章） <a class="header-anchor" href="#第一模块-web框架设计-第1-3章" aria-label="Permalink to “第一模块：Web框架设计（第1-3章）”">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第1章</td><td>Web框架核心设计</td><td>路由树、Context、net/http原理、前缀树实现</td></tr><tr><td>第2章</td><td>AOP方案设计</td><td>责任链模式、洋葱模式、中间件机制、日志/追踪/监控/Recovery</td></tr><tr><td>第3章</td><td>Web框架高级功能</td><td>文件上传、模板引擎、Option模式、Session管理</td></tr></tbody></table><h3 id="第二模块-数据层-第4-5章" tabindex="-1">第二模块：数据层（第4-5章） <a class="header-anchor" href="#第二模块-数据层-第4-5章" aria-label="Permalink to “第二模块：数据层（第4-5章）”">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第4章</td><td>SQL构造与执行</td><td>Query Builder、CRUD、事务管理、连接池</td></tr><tr><td>第5章</td><td>ORM实战项目</td><td>手写ORM框架、模型元数据、嵌套事务、博客系统数据层</td></tr></tbody></table><h3 id="第三模块-缓存层-第6-7章" tabindex="-1">第三模块：缓存层（第6-7章） <a class="header-anchor" href="#第三模块-缓存层-第6-7章" aria-label="Permalink to “第三模块：缓存层（第6-7章）”">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第6章</td><td>本地缓存与Redis客户端</td><td>LRU/LFU实现、Redis协议、连接池、Pipeline</td></tr><tr><td>第7章</td><td>缓存策略与一致性</td><td>缓存模式、穿透/击穿/雪崩、多级缓存、电商商品详情页</td></tr></tbody></table><h3 id="第四模块-微服务-第8-10章" tabindex="-1">第四模块：微服务（第8-10章） <a class="header-anchor" href="#第四模块-微服务-第8-10章" aria-label="Permalink to “第四模块：微服务（第8-10章）”">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第8章</td><td>RPC框架设计</td><td>RPC原理、序列化、gRPC、Protobuf、手写RPC框架</td></tr><tr><td>第9章</td><td>服务治理</td><td>注册发现、负载均衡、熔断降级、Sentinel原理</td></tr><tr><td>第10章</td><td>可观测性与微服务实战</td><td>链路追踪、指标监控、日志聚合、订单系统</td></tr></tbody></table><h3 id="第五模块-分布式系统-第11-12章" tabindex="-1">第五模块：分布式系统（第11-12章） <a class="header-anchor" href="#第五模块-分布式系统-第11-12章" aria-label="Permalink to “第五模块：分布式系统（第11-12章）”">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第11章</td><td>分布式事务理论</td><td>2PC/3PC/TCC/Saga、Seata架构、CAP/BASE</td></tr><tr><td>第12章</td><td>分布式事务实践</td><td>本地消息表、事务消息、电商下单扣库存</td></tr></tbody></table><h3 id="第六模块-消息队列-第13-14章" tabindex="-1">第六模块：消息队列（第13-14章） <a class="header-anchor" href="#第六模块-消息队列-第13-14章" aria-label="Permalink to “第六模块：消息队列（第13-14章）”">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第13章</td><td>Kafka与消息队列原理</td><td>Kafka架构、副本机制、Rebalance、手写消息队列</td></tr><tr><td>第14章</td><td>消息队列实战</td><td>Sarama实践、可靠性保障、日志收集监控系统</td></tr></tbody></table><h3 id="第七模块-工程化与总结-第15-16章" tabindex="-1">第七模块：工程化与总结（第15-16章） <a class="header-anchor" href="#第七模块-工程化与总结-第15-16章" aria-label="Permalink to “第七模块：工程化与总结（第15-16章）”">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第15章</td><td>工程化与CI/CD</td><td>项目规范、测试体系、CI/CD流水线、发布策略</td></tr><tr><td>第16章</td><td>总结与面试冲刺</td><td>高频考点、系统设计题、学习路径、职业发展</td></tr></tbody></table><h2 id="适合人群" tabindex="-1">适合人群 <a class="header-anchor" href="#适合人群" aria-label="Permalink to “适合人群”">​</a></h2><ul><li>有Go语言基础，想深入理解框架原理的开发者</li><li>准备Go后端面试的工程师</li><li>想从单体走向微服务架构的后端工程师</li><li>喜欢手写框架、深入源码的技术人</li></ul><h2 id="系列特色" tabindex="-1">系列特色 <a class="header-anchor" href="#系列特色" aria-label="Permalink to “系列特色”">​</a></h2><ul><li><strong>手写实现</strong>：每个核心组件都有从零到一的Go代码实现</li><li><strong>开源对比</strong>：Gin、Beego、Kratos、Seata等框架横向对比</li><li><strong>实战项目</strong>：ORM框架、多级缓存、微服务订单系统、分布式事务、日志监控系统</li><li><strong>面试导向</strong>：每章包含面试要点，最后一章集中冲刺</li></ul>',21)])])}const P=a(h,[["render",o]]);export{x as __pageData,P as default};
